WITH parsed AS (SELECT id, plan, currency, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE plan = 'pro') SELECT CASE WHEN entry_price >= 33 THEN 'HIGH' ELSE 'LOW' END AS entry_price_tier, PERCENTILE_APPROX(entry_price, 0.9) AS entry_price_p90, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, APPROX_PERCENTILE(entry_price, 0.9) AS entry_price_p90_2 FROM parsed GROUP BY CASE WHEN entry_price >= 33 THEN 'HIGH' ELSE 'LOW' END ORDER BY entry_price_p90_2 DESC;
